<?php
require_once '../config/database.php';require_once '../config/auth.php';
$u=requireAuth();$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT * FROM documentos WHERE id=?');$s->bind_param('i',$id);$s->execute();$d=$s->get_result()->fetch_assoc();if(!$d){http_response_code(404);exit('Arquivo não encontrado.');}if(!usuarioTemAcessoEmpresa($conn,$u['id'],(int)$d['empresa_id'],$u['perfil'])){http_response_code(403);exit('Sem acesso.');}$path=realpath(__DIR__.'/../../'.$d['arquivo']);$base=realpath(__DIR__.'/../../storage/uploads');if(!$path||!$base||strpos($path,$base)!==0||!is_file($path)){http_response_code(404);exit('Arquivo indisponível.');}header('Content-Type: '.($d['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.rawurlencode($d['nome_original']).'"');readfile($path);exit;
